(function(root){
'use strict';
function mount(host,{t,lang,icon,switchLanguage,example}){
 const brand='<a class="lp-brand" href="#home" aria-label="'+t('معيار — الرئيسية','Miyar — Home')+'"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i></span><span lang="ar">معيار<small lang="en" dir="ltr">MI’YĀR</small></span></a>';
 const stages=[
  [t('التطوير التنظيمي','Organization development'),t('هل نحتاج هذا المنصب؟','Do we need this position?'),t('مراجعة المبرر والبدائل ونطاق المسؤوليات قبل إضافة المنصب.','Review the business need, alternatives and responsibilities before adding a position.')],
  [t('التعويضات والمزايا','Total Rewards'),t('ما قيمته الوظيفية؟','How should it be evaluated?'),t('توثيق التقييم والدرجة ونطاق الراتب المقترح على إصدار محدد.','Record the evaluation, grade and proposed salary range against a specific revision.')],
  [t('المالية والتخطيط','Finance & Planning'),t('هل ينسجم مع الخطة؟','Does it fit the plan?'),t('مراجعة الأعداد والتكلفة والميزانية وخطة القوى العاملة.','Review headcount, cost, budget and the workforce plan.')],
  [t('صاحب الصلاحية','Final authority'),t('هل اكتملت أدلة القرار؟','Is the decision supported?'),t('اعتماد المنصب بعد اكتمال المراجعات، مع حفظ أثر القرار.','Approve after all reviews are complete, with a retained decision trail.')]
 ];
 const previewTabs=[['role',t('الوصف','Description')],['kpi',t('المؤشرات','KPIs')],['raci',t('المسؤوليات','RACI')],['approval',t('الاعتماد','Approvals')]];
 host.innerHTML=`
 <header class="lp-header"><div class="lp-wrap lp-header-inner">${brand}
  <nav class="lp-nav" aria-label="${t('التنقل الرئيسي','Main navigation')}"><a href="#home/governance" data-lp-scroll="governance">${t('الحوكمة والاعتماد','Governance')}</a><a href="#home/capabilities" data-lp-scroll="capabilities">${t('قدرات معيار','Capabilities')}</a><a href="#enterprise/overview">${t('مساحة العمل','Workspace')}</a></nav>
  <div class="lp-header-actions"><button type="button" id="lp-language" lang="${lang==='ar'?'en':'ar'}" aria-label="${t('Switch to English','التبديل إلى العربية')}">${t('English','العربية')}</button><a class="lp-signin" href="#enterprise/connection">${t('دخول المؤسسة','Organization sign in')}</a></div>
 </div></header>
 <main id="landing-main" tabindex="-1">
  <section class="lp-hero" aria-labelledby="home-heading"><div class="lp-wrap lp-hero-grid">
   <div class="lp-hero-copy"><span class="lp-eyebrow">${t('للموارد البشرية والتطوير التنظيمي وقيادات الأعمال','FOR HR, ORGANIZATION DEVELOPMENT & BUSINESS LEADERS')}</span>
    <h1 id="home-heading">${t('صَمِّم قواك العاملة.<br><em>واحكم كل قرار<br class="lp-wide-break"> بإضافة منصب.</em>','Design your workforce.<br><em>Give every position<br class="lp-wide-break"> a clear purpose.</em>')}</h1>
    <p>${t('معيار يجمع مبرر الاحتياج، والتصنيف السعودي للمهن، والوصف والتقييم، والاعتماد في مسار واحد. لتتضح قيمة كل منصب قبل أن يصبح تكلفة دائمة.','Miyar connects business need, Saudi occupation references, job design, evaluation and approvals in one workflow. Establish the value of every position before committing to its cost.')}</p>
    <div class="lp-hero-actions"><button type="button" class="lp-button lp-primary" data-lp-demo>${t('جرّب إنشاء منصب تجريبي','Try a sample position')} ${icon('arrow')}</button><a class="lp-secondary" href="#home/governance" data-lp-scroll="governance">${t('استعرض الحوكمة والاعتماد','Explore governance & approvals')}</a></div>
    <p class="lp-caption">${t('ابدأ دون تسجيل · نموذج مُعبّأ يمكنك تعديله','Start without signing in · An editable, prefilled example')}</p>
    <div id="lp-status" role="status" class="lp-status" hidden></div>
   </div>
   <div class="lp-showcase"><div class="lp-preview-label"><span>${icon('document')} ${t('مخرجات واضحة، قبل أن تبدأ','See the outcome before you start')}</span><span>${t('معاينة تفاعلية','INTERACTIVE PREVIEW')}</span></div>
    <section class="lp-document" aria-label="${t('معاينة بطاقة منصب افتراضية','Illustrative position card preview')}">
     <div class="lp-document-top"><span>${t('بطاقة الوصف والتقييم','POSITION DESIGN RECORD')}</span><span class="lp-example-tag">${t('مثال توضيحي','ILLUSTRATIVE EXAMPLE')}</span></div>
     <div class="lp-document-heading"><div><span class="lp-overline">${t('تقنية المعلومات / تطوير الأنظمة','INFORMATION TECHNOLOGY / SYSTEMS')}</span><h2>${t('مهندس برمجيات','Software engineer')}</h2></div><span class="lp-document-code" dir="ltr">SSCO<br><b>251204</b></span></div>
     <div class="lp-tabs" role="tablist" aria-label="${t('أقسام بطاقة المنصب','Position card sections')}">${previewTabs.map(([id,label],i)=>`<button type="button" role="tab" id="lp-tab-${id}" aria-controls="lp-panel-${id}" aria-selected="${i===0}" tabindex="${i===0?'0':'-1'}" data-lp-tab="${id}">${label}</button>`).join('')}</div>
     <div class="lp-preview-content">
      <div id="lp-panel-role" role="tabpanel" aria-labelledby="lp-tab-role" tabindex="0"><h3>${t('احتياج واضح. نطاق محدد.','A clear need. A defined scope.')}</h3><p>${t('تطوير تطبيق داخلي لتقليص زمن معالجة طلبات الخدمة وتحسين جودة التسليم.','Develop an internal application to reduce service-request processing time and improve delivery quality.')}</p><dl class="lp-role-facts"><div><dt>${t('المدير المباشر','Reports to')}</dt><dd>${t('مدير تطوير الأنظمة','Systems Development Manager')}</dd></div><div><dt>${t('نطاق الإشراف','Supervisory scope')}</dt><dd>${t('مساهم فردي','Individual contributor')}</dd></div></dl><div class="lp-responsibility">${icon('check')}<span>${t('تحليل المتطلبات · التطوير والاختبار · توثيق التغييرات','Requirements analysis · Development & testing · Change documentation')}</span></div></div>
      <div id="lp-panel-kpi" role="tabpanel" aria-labelledby="lp-tab-kpi" tabindex="0" hidden><h3>${t('نجاح المنصب قابل للقياس.','Make role success measurable.')}</h3><p class="lp-panel-note">${t('أهداف افتراضية للمثال، تخضع لمراجعة الجهة.','Illustrative targets, subject to organization review.')}</p><div class="lp-kpis">${[['20%',t('خفض زمن المعالجة','Reduce processing time'),t('خلال ستة أشهر','Within six months')],['95%',t('اجتياز اختبارات القبول','Acceptance tests passed'),t('قبل كل إصدار','Before each release')],['100%',t('توثيق تغييرات الإصدار','Release changes documented'),t('عند التسليم','At handover')]].map(([n,title,when])=>`<div><strong dir="ltr">${n}</strong><span>${title}<small>${when}</small></span></div>`).join('')}</div></div>
      <div id="lp-panel-raci" role="tabpanel" aria-labelledby="lp-tab-raci" tabindex="0" hidden><h3>${t('لكل مسؤولية، صاحب قرار.','Every responsibility has an owner.')}</h3><p class="lp-panel-note">${t('مثال: اختبار إصدار النظام','Example: testing a system release')}</p><dl class="lp-raci">${[['R',t('يُنفّذ','Responsible'),t('مهندس البرمجيات','Software engineer')],['A',t('يقرر ويُساءل','Accountable'),t('مدير التطوير','Development manager')],['C',t('يُستشار','Consulted'),t('الأمن السيبراني','Cybersecurity')],['I',t('يُبلّغ','Informed'),t('مالك الخدمة','Service owner')]].map(([letter,label,who])=>`<div><dt><b>${letter}</b>${label}</dt><dd>${who}</dd></div>`).join('')}</dl></div>
      <div id="lp-panel-approval" role="tabpanel" aria-labelledby="lp-tab-approval" tabindex="0" hidden><h3>${t('أربع مراجعات، وسجل واحد.','Four reviews. One decision record.')}</h3><p class="lp-panel-note">${t('محاكاة لمسار مكتمل؛ ليست اعتمادات فعلية.','A completed workflow simulation; not actual approvals.')}</p><div class="lp-approval-grid">${stages.map(([name],i)=>`<div><span class="lp-stage-number">0${i+1}</span>${icon('check')}<strong>${name}</strong><small>${t('مكتمل في المثال','Complete in this example')}</small></div>`).join('')}</div></div>
     </div><div class="lp-document-bottom"><span>${icon('shield')}${t('وصف + تقييم + أثر اعتماد','Description + evaluation + approval trail')}</span><span dir="ltr">PDF · DOCX · XLSX</span></div>
    </section>
    <div class="lp-showcase-caption">${t('انتقل بين الأقسام لاستكشاف حزمة المنصب.','Select a section to explore the position package.')}</div>
   </div>
  </div></section>
  <section class="lp-proof lp-wrap" aria-label="${t('قدرات متاحة في معيار','Available Miyar capabilities')}">
   <div><strong dir="ltr">5,041</strong><span><b>${t('مهنة في مرجع واحد','occupations in one reference')}</b><small>${t('التصنيف السعودي للمهن · إصدار 2019','Saudi occupation classification · 2019 edition')}</small></span></div>
   <div><strong dir="ltr">04</strong><span><b>${t('مراحل للاعتماد المؤسسي','institutional approval stages')}</b><small>${t('صلاحيات محددة وسجل لكل قرار','Defined permissions and a record of each decision')}</small></span></div>
   <div><strong dir="ltr">03</strong><span><b>${t('صيغ لمخرجات العمل','document export formats')}</b><small>${t('PDF رسمي · Word · Excel','Formal PDF · Word · Excel')}</small></span></div>
  </section>
  <section id="lp-capabilities" class="lp-section lp-wrap" aria-labelledby="lp-capabilities-title"><div class="lp-section-heading"><span class="lp-eyebrow">${t('قيمة يمكن مراجعتها','VALUE YOU CAN REVIEW')}</span><h2 id="lp-capabilities-title">${t('قبل أن تضيف منصباً،<br>أكمل صورة القرار.','Before adding a position,<br>complete the decision picture.')}</h2><p>${t('لغة مشتركة بين الإدارة الطالبة والموارد البشرية والمالية، من أول مبرر إلى آخر اعتماد.','A shared record for the requesting department, HR and Finance, from the first business case to the final approval.')}</p></div>
   <div class="lp-capabilities">${[
    ['layers',t('تصميم يبدأ من الاحتياج','Start with the business need'),t('وثّق البدائل، وحدد نطاق الدور، وافحص تشابه المناصب لدعم مراجعة التكرار والتضخم الوظيفي.','Document alternatives, define the role and examine overlapping positions to support reviews of duplication and headcount growth.')],
    ['target',t('مسؤوليات ترتبط بالنتائج','Connect responsibilities to results'),t('حوّل مخرجات النجاح إلى مؤشرات قابلة للمراجعة، وحدد المسؤوليات المشتركة بمصفوفة RACI.','Turn success outcomes into reviewable KPIs and clarify shared responsibilities with a RACI matrix.')],
    ['shield',t('قرار يحتفظ بأدلته','Keep the evidence with the decision'),t('اربط المنصب بمرجعه المهني، ووثّق متطلبات الترخيص والتوطين ومصادرها ضمن مراجعات الاعتماد.','Link the role to its occupation reference and document licensing and Saudization requirements and sources in the approval reviews.')]
   ].map(([ico,title,desc],i)=>`<article><span class="lp-feature-icon">${icon(ico)}</span><span class="lp-feature-number">0${i+1}</span><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div>
  </section>
  <section id="lp-governance" class="lp-governance" aria-labelledby="lp-governance-title"><div class="lp-wrap"><div class="lp-governance-intro"><div><span class="lp-eyebrow">${t('الحوكمة مدمجة في رحلة العمل','GOVERNANCE THROUGHOUT THE WORKFLOW')}</span><h2 id="lp-governance-title">${t('لا يعتمد المنصب<br><em>على رأي واحد.</em>','A position deserves<br><em>more than one perspective.</em>')}</h2></div><p>${t('تسلسل واضح للمراجعات، وفصل بين طالب المنصب ومعتمده. تُحفظ الملاحظات والنتائج على الإصدار الذي تمت مراجعته.','A defined review sequence separates the requester from the approver. Comments and results remain tied to the revision that was reviewed.')}</p></div>
   <ol class="lp-workflow">${stages.map(([title,question,desc],i)=>`<li><span class="lp-flow-number">0${i+1}</span><h3>${title}</h3><strong>${question}</strong><p>${desc}</p></li>`).join('')}</ol>
   <div class="lp-governance-foot">${icon('document')}<p>${t('تخرج النتيجة في حزمة رسمية، مع أربع خانات توقيع رقمي في PDF للاعتماد عبر قارئ متوافق.','Export a formal package with four digital signature fields in the PDF for signing in a compatible reader.')}</p><a href="#enterprise/tour">${t('شاهد دليل الاستخدام','View the user guide')} <span aria-hidden="true">${t('←','→')}</span></a></div>
  </div></section>
  <section class="lp-section lp-wrap lp-start" aria-labelledby="lp-start-title"><div><span class="lp-eyebrow">${t('من الفكرة إلى ملف جاهز للمراجعة','FROM A BUSINESS NEED TO A REVIEWABLE RECORD')}</span><h2 id="lp-start-title">${t('ابدأ بمنصب واحد.','Start with one position.')}</h2><p>${t('جرّب النموذج، وعدّل المسؤوليات، واستعرض حزمة المخرجات. وعندما تكون جاهزاً للعمل المشترك، انتقل إلى مساحة مؤسستك.','Try the example, adjust its responsibilities and preview the output package. When you are ready to collaborate, move to your organization workspace.')}</p><button type="button" class="lp-button lp-primary" data-lp-demo>${t('جرّب إنشاء منصب تجريبي','Try a sample position')} ${icon('arrow')}</button></div>
   <div class="lp-faq"><details><summary>${t('كيف يدعم معيار التصنيف والاشتراطات؟','How does Miyar support classification and requirements?')}</summary><p>${t('يتيح البحث في مرجع SSCO لعام 2019، ويظهر تنبيهات لفئات مهنية مع روابط الجهات الرسمية. يسجل المراجع المصدر وتاريخ التحقق؛ ويحتاج انطباق المتطلب وصلاحية الترخيص إلى تحقق الجهة المختصة.','Search the 2019 SSCO reference and view professional-category alerts with official authority links. Reviewers record sources and verification dates; applicability and license validity require the relevant authority’s checks.')}</p></details><details><summary>${t('كيف يُقيَّم المنصب؟','How is a position evaluated?')}</summary><p>${t('يستخدم معيار إطار نقاط تضبطه الجهة، مع إمكانية توثيق نتائج تقارير Korn Ferry الخارجية عند التصريح باستخدامها. لا يتضمن جداول تقييم مملوكة أو شهادة اعتماد من مزودي المنهجيات.','Miyar uses an organization-configured point-factor framework and can record external Korn Ferry report results under authorized use. It does not include proprietary scoring tables or certification from methodology providers.')}</p></details><details><summary>${t('هل أحتاج حساباً للتجربة؟','Do I need an account to try it?')}</summary><p>${t('يمكنك تجربة التصميم وحفظ مسودات في متصفحك دون تسجيل. العمل المشترك والصلاحيات والاعتماد تتطلب حساب مؤسسة مُعداً مسبقاً.','Try position design and save browser drafts without signing in. Shared records, permissions and approvals require a provisioned organization account.')}</p></details></div>
  </section>
 </main>
 <footer class="lp-footer"><div class="lp-wrap">${brand}<p>${t('معيار · حوكمة المناصب والقوى العاملة','Miyar · Position & workforce governance')}</p><a href="https://adeebnoor.github.io/" target="_blank" rel="noopener">${t('الفريق والتواصل','Team & contact')} ↗</a><a href="#enterprise/overview">${t('مساحة العمل','Workspace')}</a></div></footer>`;
 host.querySelector('#lp-language').onclick=switchLanguage;
 host.querySelectorAll('[data-lp-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();host.querySelector('#lp-'+a.dataset.lpScroll).scrollIntoView({behavior:'smooth',block:'start'});});
 host.querySelectorAll('[data-lp-demo]').forEach(control=>control.onclick=async()=>{
  const status=host.querySelector('#lp-status');status.hidden=false;status.textContent=t('جارٍ تجهيز النموذج…','Preparing the example…');
  host.querySelectorAll('[data-lp-demo]').forEach(b=>b.disabled=true);
  try{await example();status.hidden=true;}catch{status.textContent=t('تعذر تحميل النموذج. تحقق من الاتصال ثم أعد المحاولة.','The example could not load. Check your connection and try again.');status.scrollIntoView({block:'nearest'});}
  finally{host.querySelectorAll('[data-lp-demo]').forEach(b=>b.disabled=false);}
 });
 const tabs=[...host.querySelectorAll('[data-lp-tab]')];
 function select(tab){for(const x of tabs){const selected=x===tab;x.setAttribute('aria-selected',String(selected));x.tabIndex=selected?0:-1;host.querySelector('#lp-panel-'+x.dataset.lpTab).hidden=!selected;}}
 tabs.forEach((tab,i)=>{tab.onclick=()=>select(tab);tab.onkeydown=e=>{let n;if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else if(e.key==='ArrowRight')n=(i+(lang==='ar'?-1:1)+tabs.length)%tabs.length;else if(e.key==='ArrowLeft')n=(i+(lang==='ar'?1:-1)+tabs.length)%tabs.length;else return;e.preventDefault();select(tabs[n]);tabs[n].focus();};});
}
root.MiyarLanding={mount};
})(window);
